// Package frontend embeds the production static bundle of the original React UI.
//
// The bundle is generated by Vite in this directory (see README.md) and checked
// into the source tree, because the Go release pipeline must build the single
// binary without a Node toolchain. Go's embed directive cannot reach outside the
// package directory, so this package owns the files and the HTTP layer imports
// frontend.Dist instead of copying the output into internal/server.
//
// Paths inside Dist keep the generated layout: "dist/index.html" and
// "dist/assets/<name>". The static HTML shell is what every original page route
// serves; the browser then talks to the JSON API only.
package frontend

import "embed"

// Dist is the complete Vite output directory, embedded verbatim.
//
// The asset handler only serves the allow-listed flat files under
// dist/assets, so anything else that lands here (editor droppings, build
// leftovers) is reachable from Go code but never exposed over HTTP.
//
//go:embed dist
var Dist embed.FS
